using System;
using System.Collections.Generic;
using System.Diagnostics;
using WoWProbe;
class CampaignSimulatorTests
{
    static int passed,failed;
    static void Test(string n,Action a){try{a();passed++;Console.WriteLine("PASS "+n);}catch(Exception e){failed++;Console.WriteLine("FAIL "+n+": "+e.Message);}}
    static void Assert(bool b,string reason){if(!b)throw new Exception(reason);}
    static CampaignPlan Plan(){var p=CampaignFixtures.Plan();p.Settings.ProtectedItemIds.Add(1004);return p;}
    static OperationCommand Run(CampaignSimulator s,int maximum=150000){for(int i=0;i<maximum;i++){var c=s.Step();if(c.Action==OperationAction.Stop||c.Action==OperationAction.Completed)return c;}throw new Exception("virtual step bound; "+s.Engine.Status+": "+s.Engine.LastReason);}
    static HashSet<uint> Inventory(CampaignSimulator s){var ids=new HashSet<uint>();for(int i=0;i<6;i++){var o=s.Sample();if(!o.Item.Empty)ids.Add(o.Item.ItemId);}return ids;}
    static int Main()
    {
        Test("complete virtual campaign restores recovers sells protects and resumes",delegate{var s=new CampaignSimulator(Plan());var c=Run(s);Assert(c.Action==OperationAction.Completed,s.Engine.Status+": "+s.Engine.LastReason);Assert(s.Completed&&s.Kills>=2&&s.SkillCasts>=6&&s.Deaths==1&&s.Resurrections==1&&s.Engine.RecoveryCount==1&&s.Engine.VendorCount==1,"missing full interruption cycle");Assert(s.Sales==2&&s.Heals>0&&s.Drinks>0&&s.Loots>0&&s.Skins>0,"missing combat recovery loot skin sale");var ids=Inventory(s);Assert(ids.Contains(1002)&&ids.Contains(1003)&&ids.Contains(1004)&&ids.Contains(1006),"protected food quest or unsellable item lost");Assert(s.InputEvents==0,"native input emitted");});
        Test("reversed farm campaign keeps both interruption routes and finishes",delegate{var p=Plan();p.FarmReverse=true;var s=new CampaignSimulator(p);Assert(Run(s).Action==OperationAction.Completed,s.Engine.Status+": "+s.Engine.LastReason);Assert(s.Engine.RecoveryCount==1&&s.Engine.VendorCount==1&&s.Sales==2,"reverse campaign lost interruption or return");});
        Test("simultaneous death and full bags recover before merchant return",delegate{var s=new CampaignSimulator(Plan()){InjectDeathAfterKills=1,InjectBagFullAfterKills=1};Assert(Run(s).Action==OperationAction.Completed,s.Engine.Status+": "+s.Engine.LastReason);Assert(s.Deaths==1&&s.Resurrections==1&&s.Engine.RecoveryCount==1&&s.Engine.VendorCount==1&&s.Sales==2,"combined interruption lost its pending vendor or original resume");});
        Test("missing real corpse evidence stops without pretending resurrection",delegate{var s=new CampaignSimulator(Plan()){MissingCorpse=true};Assert(Run(s).Action==OperationAction.Stop&&s.Deaths==1&&s.Resurrections==0&&s.InputEvents==0,"missing corpse was recovered");});
        Test("missing supplies cannot pretend to restore health or mana",delegate{var s=new CampaignSimulator(Plan()){NoSupplies=true};Assert(Run(s).Action==OperationAction.Stop&&s.Kills==0&&s.Heals==0&&s.Drinks==0,"supply fault did not stop");});
        Test("wrong merchant never receives an inventory sale",delegate{var s=new CampaignSimulator(Plan()){WrongMerchant=true};Assert(Run(s).Action==OperationAction.Stop&&s.Sales==0&&s.InputEvents==0,"wrong merchant accepted");});
        Test("unknown inventory metadata cannot become a sale",delegate{var s=new CampaignSimulator(Plan()){UnknownItemMetadata=true};Assert(Run(s).Action==OperationAction.Stop&&s.Sales==0,"unknown item sold");});
        Test("merchant closing before sale cannot turn right click into item use",delegate{var s=new CampaignSimulator(Plan()){MerchantClosesBeforeSale=true};Assert(Run(s).Action==OperationAction.Stop&&s.Sales==0,"closed merchant accepted a sale");});
        Test("virtual actuator independently rejects unsafe actions and partial geometry",delegate{var s=new CampaignSimulator(Plan());bool rejected=false;try{s.Apply(new OperationCommand{Action=OperationAction.RightClick,Purpose=OperationPurpose.Sell,HoldMilliseconds=80,Bag=0,Slot=1});}catch(InvalidOperationException){rejected=true;}Assert(rejected&&s.Sales==0,"actuator trusted unproven sale");rejected=false;try{s.Apply(new OperationCommand{Action=OperationAction.LeftClick,Purpose=OperationPurpose.Resurrect,HoldMilliseconds=80});}catch(InvalidOperationException){rejected=true;}Assert(rejected&&s.Resurrections==0,"actuator trusted unproven resurrection");});
        Test("snapshot mutation cannot change the virtual world",delegate{var s=new CampaignSimulator(Plan());var o=s.Sample();o.Farm.Health=0;o.BagSizes[0]=0;o.Occupancy[0]=0;o.Item.ItemId=0;var next=s.Sample();Assert(next.Farm.Health>0&&next.BagSizes[0]==6&&next.Item.ItemId!=0,"sample leaked mutable simulator data");});
        Test("two virtual hours repeatedly recover and sell without native input",delegate{var p=Plan();p.FarmLoop=true;var s=new CampaignSimulator(p){RepeatInterruptions=true};var wall=Stopwatch.StartNew();int steps=0;while(s.ElapsedMilliseconds<7200000&&steps<150000){var c=s.Step();Assert(c.Action!=OperationAction.Stop,s.Engine.Status+": "+s.Engine.LastReason);Assert(c.Action!=OperationAction.Completed,"loop campaign completed early");steps++;}wall.Stop();Assert(s.ElapsedMilliseconds>=7200000&&s.Engine.RecoveryCount>2&&s.Engine.VendorCount>2&&s.Deaths>2&&s.Sales>=6&&s.InputEvents==0,"two-hour repeated-interruption coverage missing");Console.WriteLine("VIRTUAL_STRESS elapsed_ms="+s.ElapsedMilliseconds+" wall_ms="+wall.ElapsedMilliseconds+" steps="+steps+" recoveries="+s.Engine.RecoveryCount+" vendors="+s.Engine.VendorCount+" input=0");});
        Console.WriteLine("Campaign simulator tests: "+passed+" passed, "+failed+" failed. Elapsed campaign time is synthetic; no game or native input was used.");return failed==0?0:1;
    }
}
